export const meta = {
  name: 'alpha-beta',
  description: 'Run two trivial agents in parallel: one replies alpha, one replies beta',
  phases: [{ title: 'Words' }],
}

phase('Words')
const [a, b] = await parallel([
  () => agent('Reply with only the single word: alpha', { label: 'alpha', phase: 'Words' }),
  () => agent('Reply with only the single word: beta', { label: 'beta', phase: 'Words' }),
])
return { a, b }

